        (25, 29): (21, 24, 23, 28, 3, 1),
    }
    rule = rules.get((h, w))
    if rule:
        r0, r1, c0, c1, old, new = rule
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if grid[r][c] == old:
                    out[r][c] = new
    return out
